(()=>{
const canvas=document.querySelector('#earth'),ctx=canvas.getContext('2d'), wrap=canvas.parentElement;
const D=Math.PI/180,clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const cities=[['Гуанчжоу',113.2644,23.1291,0],['Шэньчжэнь',114.0579,22.5431,0],['Гонконг',114.1694,22.3193,0],['Пекин',116.4074,39.9042,1],['Сеул',126.978,37.5665,1],['Пхукет',98.3923,7.88,2],['Чэнду',104.0668,30.5728,2]];
const colors=['#419dff','#bd65ff','#ffad36'], routes=[[0,1,2],[3,4],[5,6]], centers=[[113.8,22.7,6.6],[121,39,2.4],[101,19,1.25]];
const countries=[['Китай',102,36],['Монголия',105,47],['Япония',139,36],['Индия',78,22],['Таиланд',101,15],['Вьетнам',107,16],['Мьянма',96,21],['Филиппины',123,12],['Россия',110,57],['Индонезия',113,-5],['Казахстан',68,48],['Малайзия',109,4]];
let lon=112,lat=25,zoom=1,selected=-1,texture=null,tw=0,th=0,w=0,h=0,ratio=1,frame=0,buffer=null,bctx=null,geometry=null,geometryKey='',points=new Map(),gesture=null;
// Natural Earth map embedded as run-length encoded palette indices. No network or Canvas readback.
tw=2160;th=1080;texture=new Uint8Array(tw*th);
const encoded=atob('');let offset=0;
for(let i=0;i<encoded.length;i+=3){const count=encoded.charCodeAt(i+1)+(encoded.charCodeAt(i+2)<<8);texture.fill(encoded.charCodeAt(i),offset,offset+count);offset+=count}
if(offset!==texture.length)throw new Error('Invalid map texture');
const palette=[[19,43,72],[73,96,88],[105,127,116]];
canvas.dataset.geography='ready';

function request(){if(!frame)frame=requestAnimationFrame(()=>{frame=0;draw()})}
function resize(){const rect=canvas.getBoundingClientRect();w=rect.width;h=rect.height;ratio=Math.min(devicePixelRatio||1,1.5,1000/w);canvas.width=Math.round(w*ratio);canvas.height=Math.round(h*ratio);request()}
new ResizeObserver(resize).observe(canvas);
function basis(){const a=lon*D,b=lat*D;return [Math.sin(a),Math.cos(a),Math.sin(b),Math.cos(b)]}
function radius(){return Math.min(w*.72,h*.91)*zoom}
function project(x,y){const [sa,ca,sb,cb]=basis(),p=y*D,l=x*D-lon*D,cp=Math.cos(p),sp=Math.sin(p),z=sb*sp+cb*cp*Math.cos(l);return [w/2+radius()*cp*Math.sin(l),h/2-radius()*(cb*sp-sb*cp*Math.cos(l)),z]}
function draw(){if(!w||!h)return;ctx.setTransform(ratio,0,0,ratio,0,0);ctx.clearRect(0,0,w,h);const R=radius(),cx=w/2,cy=h/2;
 const sky=ctx.createRadialGradient(cx,cy,30,cx,cy,Math.max(w,h)*.7);sky.addColorStop(0,'#11263b');sky.addColorStop(1,'#060e1a');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
 for(let i=0;i<88;i++){let x=((i*137.508)%100)/100*w,y=((i*61.73)%100)/100*h;ctx.fillStyle=i%8===0?'#697c90':'#23364a';ctx.fillRect(x,y,i%8===0?1.3:.7,i%8===0?1.3:.7)}
 ctx.save();ctx.shadowColor='#699fd2';ctx.shadowBlur=14;ctx.beginPath();ctx.arc(cx,cy,R,0,Math.PI*2);ctx.fillStyle='#192e43';ctx.fill();ctx.restore();
 if(texture){const bw=canvas.width,bh=canvas.height,rr=R*ratio,xc=bw/2,yc=bh/2,key=[bw,bh,rr].join(',');if(key!==geometryKey){geometryKey=key;geometry=[];for(let j=0;j<bh;j++){const y=(yc-j-.5)/rr;for(let i=0;i<bw;i++){const x=(i+.5-xc)/rr,q=1-x*x-y*y;if(q>0){const z=Math.sqrt(q);geometry.push(i+j*bw,x,y,z)}}}buffer=document.createElement('canvas');buffer.width=bw;buffer.height=bh;bctx=buffer.getContext('2d')}
 const pixels=bctx.createImageData(bw,bh),out=pixels.data,[sa,ca,sb,cb]=basis();for(let i=0;i<geometry.length;i+=4){const idx=geometry[i]*4,x=geometry[i+1],y=geometry[i+2],z=geometry[i+3];const yy=clamp(y*cb+z*sb,-1,1),v=Math.asin(yy),u=Math.atan2(x,z*cb-y*sb)+lon*D;const tx=((Math.floor((u/Math.PI+1)*tw/2)%tw)+tw)%tw,ty=clamp(Math.floor((.5-v/Math.PI)*th),0,th-1),k=texture[ty*tw+tx],rgb=palette[k];const shade=.68+.32*Math.max(0,z*.94-y*.18-x*.12),rim=Math.pow(1-z,5);out[idx]=rgb[0]*shade+rim*38;out[idx+1]=rgb[1]*shade+rim*62;out[idx+2]=rgb[2]*shade+rim*90;out[idx+3]=255}bctx.putImageData(pixels,0,0);ctx.drawImage(buffer,0,0,w,h)}
 ctx.font='600 11px -apple-system,BlinkMacSystemFont,Arial,sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';for(const [name,x,y] of countries){const p=project(x,y);if(p[2]>.18&&p[0]>25&&p[0]<w-25&&p[1]>20&&p[1]<h-20){ctx.fillStyle='#a5adb4aa';ctx.fillText(name,p[0],p[1])}}
 function vector(c){let a=c[1]*D,b=c[2]*D;return [Math.cos(b)*Math.cos(a),Math.cos(b)*Math.sin(a),Math.sin(b)]}
 routes.forEach((route,k)=>{ctx.strokeStyle=colors[k];ctx.lineWidth=selected===k?2.5:1.6;ctx.globalAlpha=selected===-1||selected===k?.85:.22;for(let i=0;i<route.length-1;i++){const a=vector(cities[route[i]]),b=vector(cities[route[i+1]]);ctx.beginPath();let started=false;for(let j=0;j<=60;j++){const t=j/60,v=a.map((n,l)=>n*(1-t)+b[l]*t),p=project(Math.atan2(v[1],v[0])/D,Math.atan2(v[2],Math.hypot(v[0],v[1]))/D);if(p[2]>0){if(started)ctx.lineTo(p[0],p[1]);else ctx.moveTo(p[0],p[1]);started=true}else started=false}ctx.stroke()}});ctx.globalAlpha=1;
 const displayed=[];cities.forEach((c,i)=>{const [x,y,z]=project(c[1],c[2]);if(z<.02||x<0||x>w||y<0||y>h)return;const active=selected===-1||selected===c[3];ctx.globalAlpha=active?1:.25;ctx.beginPath();ctx.arc(x,y,active?6:3.5,0,Math.PI*2);ctx.fillStyle=colors[c[3]];ctx.shadowColor=colors[c[3]];ctx.shadowBlur=active?7:0;ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#d9e8ff';ctx.lineWidth=.8;ctx.stroke();if(active)displayed.push({c,i,x,y})});ctx.globalAlpha=1;
 ctx.font='600 12px -apple-system,BlinkMacSystemFont,Arial,sans-serif';ctx.textBaseline='middle';ctx.textAlign='left';for(const {c,i,x,y} of displayed){let dx=10,dy=-12;if(i===0){dx=-12-ctx.measureText(c[0]).width;dy=-17}if(i===1){dx=15;dy=-2}if(i===2){dx=10;dy=20}if(i===3){dx=-ctx.measureText(c[0]).width-10;dy=-12}if(i===6){dx=-ctx.measureText(c[0]).width-10;dy=-12}const width=ctx.measureText(c[0]).width,lx=clamp(x+dx,5,w-width-5),ly=clamp(y+dy,10,h-10);ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(lx+(dx<0?width:0),ly);ctx.strokeStyle=colors[c[3]]+'a0';ctx.lineWidth=.8;ctx.stroke();ctx.lineWidth=3.5;ctx.strokeStyle='#0c1522';ctx.strokeText(c[0],lx,ly);ctx.fillStyle='#f0f3f6';ctx.fillText(c[0],lx,ly)}
}
function focus(i){selected=i;[lon,lat,zoom]=i<0?[112,25,1]:centers[i];document.querySelectorAll('[data-route]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.route===i)));request()}
function zoomBy(f){zoom=clamp(zoom*f,.48,9);request()}
canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);points.set(e.pointerId,[e.clientX,e.clientY]);gesture=null;canvas.classList.add('dragging')});
canvas.addEventListener('pointermove',e=>{if(!points.has(e.pointerId))return;const old=points.get(e.pointerId);points.set(e.pointerId,[e.clientX,e.clientY]);if(points.size===1){lon-=(e.clientX-old[0])*180/(Math.PI*radius());lat=clamp(lat+(e.clientY-old[1])*180/(Math.PI*radius()),-85,85);request()}else if(points.size===2){const [a,b]=[...points.values()],dist=Math.hypot(a[0]-b[0],a[1]-b[1]);if(gesture)zoomBy(dist/gesture);gesture=dist}});
function release(e){points.delete(e.pointerId);gesture=null;if(!points.size)canvas.classList.remove('dragging')}
canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);canvas.addEventListener('lostpointercapture',release);canvas.addEventListener('wheel',e=>{e.preventDefault();zoomBy(Math.exp(-e.deltaY*.0015))},{passive:false});canvas.addEventListener('keydown',e=>{let handled=true;switch(e.key){case 'ArrowLeft':lon-=8/zoom;break;case 'ArrowRight':lon+=8/zoom;break;case 'ArrowUp':lat=clamp(lat+8/zoom,-85,85);break;case 'ArrowDown':lat=clamp(lat-8/zoom,-85,85);break;case '+':case '=':zoomBy(1.2);break;case '-':zoomBy(1/1.2);break;case 'Home':focus(-1);break;default:handled=false}if(handled){e.preventDefault();request()}});
document.querySelectorAll('[data-route]').forEach(b=>b.addEventListener('click',()=>focus(+b.dataset.route)));document.querySelector('#zoom-in').onclick=()=>zoomBy(1.25);document.querySelector('#zoom-out').onclick=()=>zoomBy(.8);document.querySelector('#reset-map').onclick=()=>focus(-1);
})();
